// RUN: %clang %s --target=aie2 -nostdlibinc -S -emit-llvm -nostdlibinc -o - | FileCheck %s
// RUN: %clang %s --target=aie2p -nostdlibinc -S -emit-llvm -nostdlibinc -o - | FileCheck %s -check-prefix=CHECK-AIE2P

template <aie_dm_resource Resource, typename T> struct add_memory_bank { using type = T; };
template <aie_dm_resource Resource, typename T>
using add_memory_bank_t = typename add_memory_bank<Resource, T>::type;
template <aie_dm_resource Resource = aie_dm_resource::none>
__attribute__((always_inline))
void store_v_aligned(bfloat16 *ptr, v32bfloat16 data) {
    using aliased_type = add_memory_bank_t<Resource, aie_dm_resource_set_t<v32bfloat16, aie_dm_resource_get_v<bfloat16>>>;
    *(aliased_type*)ptr = data;
}
